from qiskit import QuantumCircuit, QuantumRegister
import math
from qiskit.circuit.library import QFT, MCPhaseGate

def solve(n: int, m: int, L: int, S: list[int], theta: float) -> QuantumCircuit:
    x = QuantumRegister(n, 'x')
    y = QuantumRegister(m, 'y')
    qc = QuantumCircuit(x, y)

    if m == 0:
        return qc

    # ---- compute f(x) into y ----
    qft = QFT(m, do_swaps=False)
    qc.append(qft, y)

    for k in range(n):
        c = S[k] % (1 << m)
        if c == 0:
            continue
        for j in range(m):
            denom = 1 << (m - j)
            c_mod = c % denom
            if c_mod == 0:
                continue
            angle = 2.0 * math.pi * c_mod / denom
            qc.crz(angle, x[k], y[j])

    iqft = QFT(m, do_swaps=False).inverse()
    qc.append(iqft, y)

    # ---- phase if y == L ----
    for j in range(m):
        if ((L >> j) & 1) == 0:
            qc.x(y[j])

    if m > 0:
        qc.append(MCPhaseGate(m, theta), y)

    for j in range(m):
        if ((L >> j) & 1) == 0:
            qc.x(y[j])

    # ---- uncompute y ----
    qc.append(QFT(m, do_swaps=False), y)
    for k in range(n):
        c = S[k] % (1 << m)
        if c == 0:
            continue
        for j in range(m):
            denom = 1 << (m - j)
            c_mod = c % denom
            if c_mod == 0:
                continue
            angle = 2.0 * math.pi * c_mod / denom
            qc.crz(-angle, x[k], y[j])
    qc.append(QFT(m, do_swaps=False).inverse(), y)

    return qc
